def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if len(stack) > 0:  # There is at least one unmatched '['
                    nested = True

    return nested

